import React, { useState } from 'react';
import { Outlet } from 'react-router-dom';
import GarageNavbar from './GarageNavbar';
import GarageSidebar from './GarageSidebar';

/**
 * GarageLayout - Layout หลักสำหรับหน้าอู่ซ่อม
 * ประกอบด้วย: Navbar (บน) + Sidebar (ซ้าย) + Content (กลาง)
 * 
 * TODO: Backend Integration Points
 * 1. User Authentication - ตรวจสอบ token/session
 *    - GET /api/auth/me - ดึงข้อมูล user ที่ login อยู่
 *    - ถ้าไม่มี token → redirect ไป /login
 * 
 * 2. User Role Check - ตรวจสอบว่าเป็น garage role จริงหรือไม่
 *    - ถ้า role ไม่ใช่ 'garage' → redirect ไปหน้าที่เหมาะสม
 */
const GarageLayout = () => {
  // State สำหรับ toggle sidebar
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);

  // TODO: Backend - ดึงข้อมูล user และ garage จาก context/redux หรือ API
  // const { user, garage, loading } = useAuth();
  // const navigate = useNavigate();

  // TODO: Backend - ตรวจสอบ authentication
  // useEffect(() => {
  //   if (!loading && !user) {
  //     navigate('/login');
  //   }
  //   if (user && user.role !== 'garage') {
  //     navigate(`/${user.role}/dashboard`);
  //   }
  // }, [user, loading, navigate]);

  // Mock user and garage data (จะถูกแทนที่ด้วยข้อมูลจริงจาก Backend)
  const mockUser = {
    id: '1',
    name: 'นายสมชาย ช่างซ่อม',
    email: 'somchai@garage.com',
    role: 'garage',
    position: 'ช่างหัวหน้า',
    avatar: null,
  };

  const mockGarage = {
    id: 'G001',
    name: 'อู่ซ่อมรถยนต์ ABC',
    phone: '02-123-4567',
    address: '123 ถนนพระราม 4 แขวงสีลม เขตบางรัก กรุงเทพฯ 10500',
  };

  return (
    <div className="min-h-screen bg-neutral-50">
      {/* Navbar */}
      <GarageNavbar 
        user={mockUser}
        garage={mockGarage}
        onToggleSidebar={() => setSidebarCollapsed(!sidebarCollapsed)}
      />

      {/* Main Container */}
      <div className="flex">
        {/* Sidebar */}
        <GarageSidebar collapsed={sidebarCollapsed} />

        {/* Main Content Area */}
        <main className="flex-1 p-6 overflow-y-auto">
          <div className="max-w-7xl mx-auto animate-fade-in">
            <Outlet />
          </div>
        </main>
      </div>
    </div>
  );
};

export default GarageLayout;
